import re

# Read the June 2017 bulletin to get Oct-Dec 2016 data
with open('/app/resources/treasury_bulletin_2017_06_page_22.txt', 'r') as f:
    content = f.read()

rows = re.findall(r'<tr>(.*?)</tr>', content, re.DOTALL)

print("June 2017 bulletin - looking for Oct, Nov, Dec 2016:")
for row in rows:
    cols = re.findall(r'<td>(.*?)</td>', row)
    if len(cols) > 8:
        first_col = cols[0].strip()
        ocs_str = cols[8].strip().replace(',', '')

        if ocs_str and ocs_str != '-' and ocs_str != 'n.a.':
            try:
                ocs_value = float(ocs_str)
            except:
                continue

            if '2016' in first_col or first_col in ['Oct', 'Nov', 'Dec']:
                print(f"{first_col} -> OCS: {ocs_value}")
