python3 << 'EOF'
import json

# Let's look at the JSON file for more comprehensive data
with open('/app/resources/treasury_bulletin_2016_12.json', 'r') as f:
    data = json.load(f)

# Search for OCS-related data
def find_ocs(obj, path=""):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if 'OCS' in key.upper() or 'continental' in key.lower() or 'royalty' in key.lower() or 'rent' in key.lower():
                print(f"{path}{key}: {value}")
            find_ocs(value, path + key + ".")
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_ocs(item, path + f"[{i}].")

find_ocs(data)
